// A branchless word builder, selected once per block (not once per row).
template<Op op,class T>static bool test_bulk(T x,const Pred&p){
 if constexpr(op==EQ)return U(x)==p.value;
 if constexpr(op==NE)return U(x)!=p.value;
 if constexpr(op==LT)return U(x)<p.value;
 if constexpr(op==LE)return U(x)<=p.value;
 if constexpr(op==GT)return U(x)>p.value;
 if constexpr(op==GE)return U(x)>=p.value;
 if constexpr(op==LUT)return U(x)<p.lut.size()&&p.lut[U(x)];
 return false;
}
