#include <bit>
#include <type_traits>
#if defined(__SSE2__) && (defined(__x86_64__) || defined(__i386__))
#include <emmintrin.h>
#define FACTORIAL_COMPILED_SSE2 1
#else
#define FACTORIAL_COMPILED_SSE2 0
#endif
static bool compare_mask_enabled = false;
static bool compare_mask_available() {
#if FACTORIAL_COMPILED_SSE2
 __builtin_cpu_init(); return __builtin_cpu_supports("sse2");
#else
 return false;
#endif
}
#if FACTORIAL_COMPILED_SSE2
template<Op op,bool narrow>static inline __m128i compare_mask_lanes(__m128i a,__m128i b) {
 __m128i eq;
 if constexpr(narrow)eq=_mm_cmpeq_epi16(a,b);else eq=_mm_cmpeq_epi32(a,b);
 if constexpr(op==EQ)return eq;
 if constexpr(op==NE)return _mm_xor_si128(eq,_mm_set1_epi32(-1));
 __m128i sign;
 if constexpr(narrow)sign=_mm_set1_epi16(-32768);else sign=_mm_set1_epi32(INT32_MIN);
 a=_mm_xor_si128(a,sign);b=_mm_xor_si128(b,sign);
 __m128i lt,gt;
 if constexpr(narrow){lt=_mm_cmpgt_epi16(b,a);gt=_mm_cmpgt_epi16(a,b);}
 else{lt=_mm_cmpgt_epi32(b,a);gt=_mm_cmpgt_epi32(a,b);}
 if constexpr(op==LT)return lt;
 if constexpr(op==LE)return _mm_or_si128(lt,eq);
 if constexpr(op==GT)return gt;
 if constexpr(op==GE)return _mm_or_si128(gt,eq);
 return _mm_setzero_si128();
}
static inline U compact_even_mask(U m) {
 m &= 0x5555U; m=(m|(m>>1))&0x3333U;
 m=(m|(m>>2))&0x0f0fU; return (m|(m>>4))&0x00ffU;
}
#endif
template<Op op,class T>static bool factorial_simd_words(const T*a,U n,const Pred&p,B&out,U off) {
 if(!compare_mask_enabled)return false;
 if constexpr(op==LUT || !(std::is_same_v<T,uint16_t> || std::is_same_v<T,uint32_t>))return false;
 else {
#if FACTORIAL_COMPILED_SSE2
  need((off&63)==0,"compare-mask word alignment");
  // All u16 values are below this threshold; do not truncate an arbitrary u32 literal.
  if constexpr(std::is_same_v<T,uint16_t>)if(p.value>65535U){
   bool truth=test_bulk<op>(uint16_t(0),p);
   for(U i=0;i<n;i+=64){U take=std::min<U>(64,n-i);out[(off+i)>>6]=truth?(take==64?~uint64_t(0):((uint64_t(1)<<take)-1)):0;}
   return true;
  }
  constexpr U lanes=std::is_same_v<T,uint16_t>?8:4;
  __m128i threshold;
  if constexpr(lanes==8)threshold=_mm_set1_epi16(std::bit_cast<int16_t>(uint16_t(p.value)));
  else threshold=_mm_set1_epi32(std::bit_cast<int32_t>(uint32_t(p.value)));
  for(U i=0;i<n;i+=64){
   U take=std::min<U>(64,n-i),j=0;uint64_t word=0;
   for(;j+lanes<=take;j+=lanes){
    // The load is unaligned but remains wholly inside [0,n); no overread of tails.
    __m128i values=_mm_loadu_si128(reinterpret_cast<const __m128i*>(a+i+j));
    __m128i result=compare_mask_lanes<op,lanes==8>(values,threshold);U mask;
    if constexpr(lanes==8)mask=compact_even_mask(U(_mm_movemask_epi8(result)));
    else mask=U(_mm_movemask_ps(_mm_castsi128_ps(result)));
    word|=uint64_t(mask)<<j;
   }
   for(;j<take;++j)word|=uint64_t(test_bulk<op>(a[i+j],p))<<j;
   out[(off+i)>>6]=word; // fresh word zeros every logical-tail padding bit
  }
  return true;
#else
  return false;
#endif
 }
}
