 for(U i=0;i<(n+63)/64;++i)expected[2+i]=0;
 Pred p{op,threshold,{}};
 for(U i=0;i<n;++i)if(p.test(U(values[i])))expected[2+i/64]|=uint64_t(1)<<(i%64);
