// Inject after build3, before construct3. No frozen evaluator is modified here.
// Bit 0: replace only logically NULL rows by the first valid code in their block.
// Bit 1: use that representative for the final physical block's padding.
// Modes 0 and 3 are the primary comparison; 1 and 2 separate the two effects.
unsigned physical_fill_mode = 0;

static void check_physical_validity3(size_t n, const B& valid) {
    need(valid.size() == (n + 63) / 64, "physical-fill validity length");
    if (n % 64) need((valid.back() >> (n % 64)) == 0, "physical-fill validity padding");
}

static N build_factorial3(const std::vector<U>& a, const B& valid, U family) {
    need(physical_fill_mode <= 3, "physical-fill mode");
    need(!a.empty() && a.size() <= 100000000 && family3(family), "physical-fill input");
    check_physical_validity3(a.size(), valid);
    if (physical_fill_mode == 0) return build3(a, family);

    const U n = U(a.size());
    std::vector<U> physical = a;
    U last_representative = 0;
    for (U off = 0; off < n; off += V) {
        const U end = off + std::min(V, n - off);
        U representative = 0;
        for (U i = off; i < end; ++i) {
            if (valid3(valid, i)) { representative = a[i]; break; }
        }
        if (physical_fill_mode & 1U) {
            for (U i = off; i < end; ++i) {
                if (!valid3(valid, i)) physical[i] = representative;
            }
        }
        last_representative = representative;
    }
    // RUNS must retain exact logical coverage: its frozen emitter does not clip.
    if ((physical_fill_mode & 2U) && family != 0 && n % V) {
        physical.resize(size_t(n) + V - n % V, last_representative);
    }
    auto root = build3(physical, family);
    root->n = n;
    // MAP and its CHUNKS child must agree for load_node's unary-row certificate.
    // The leaf blocks stay V rows, including any charged PATCH tail positions.
    if (family == 3) {
        need(root->kind == MAP && root->children.size() == 1 &&
             root->children[0]->kind == CHUNKS, "physical-fill dictionary shape");
        root->children[0]->n = n;
    }
    return root;
}

static void verify_logical_source3(const std::vector<U>& decoded,
                                   const std::vector<U>& source, const B& valid) {
    need(physical_fill_mode <= 3, "physical-fill verify mode");
    need(decoded.size() == source.size(), "logical source length");
    check_physical_validity3(source.size(), valid);
    for (size_t i = 0; i < source.size(); ++i) {
        if (!(physical_fill_mode & 1U) || valid3(valid, U(i))) {
            need(decoded[i] == source[i], "logical source reconstruction");
        }
    }
}

// Source-authored mathematical controls; never execute before the CPU grant.
// Entire signed-original/validity answer banks are checked, not only counts.
static int selftest_physical_fill3() {
    struct RestoreMode {
        unsigned saved;
        ~RestoreMode() { physical_fill_mode = saved; }
    } restore{physical_fill_mode};
    uint64_t trees = 0, answers = 0, banks = 0;
    auto signed_test = [](int64_t x, U op, int64_t y) {
        switch (op) {
        case EQ: return x == y;
        case NE: return x != y;
        case LT: return x < y;
        case LE: return x <= y;
        case GT: return x > y;
        case GE: return x >= y;
        default: throw std::runtime_error("physical-fill fixture opcode");
        }
    };

    for (U mode = 0; mode != 4; ++mode) {
        physical_fill_mode = mode;
        for (U width : {16U, 32U}) {
            const int64_t lo = -(int64_t(1) << (width - 1));
            const int64_t hi = (int64_t(1) << (width - 1)) - 1;
            const std::array<int64_t, 7> extremes = {hi, lo, lo + 1, -1, 0, 1, hi - 1};
            for (U n : {1U, 63U, 64U, 65U, 1023U, 1024U, 1031U, 2049U}) {
                for (U pattern = 0; pattern != 5; ++pattern) {
                    std::vector<U> source(n);
                    std::vector<int64_t> original(n);
                    B valid((n + 63) / 64, 0);
                    for (U i = 0; i < n; ++i) {
                        original[i] = extremes[(i / 11 + i / V) % extremes.size()];
                        bool live = true;
                        if (pattern == 1) live = i % 13 != 0;
                        if (pattern == 2) live = false;
                        if (pattern == 3) { live = i == n - 1; original[i] = hi; }
                        // A prior live block must not supply the last all-NULL block.
                        if (pattern == 4) live = i / V != (n - 1) / V;
                        bit(valid, i, live);
                        source[i] = live ? U(original[i] - lo) : 0;
                    }
                    for (U family : {0U, 2U, 3U, 5U}) {
                        const U codec = family == 5 ? 2 : family;
                        auto root = build_factorial3(source, valid, family);
                        need(root->n == n, "physical-fill logical root rows");
                        shape(*root, codec);
                        std::ostringstream encoded(std::ios::binary);
                        save_node(encoded, *root);
                        if (mode == 0 || (mode == 2 && family == 0)) {
                            auto baseline = build3(source, family);
                            std::ostringstream canonical(std::ios::binary);
                            save_node(canonical, *baseline);
                            need(encoded.str() == canonical.str(), "physical-fill unchanged arm bytes");
                        }
                        // Roundtrip through the original descriptor validator, including
                        // MAP/CHUNKS row equality and PATCH positions in padded leaf rows.
                        std::istringstream input(encoded.str(), std::ios::binary);
                        auto loaded = load_node(input);
                        need(input.peek() == std::char_traits<char>::eof(), "physical-fill serialized suffix");
                        shape(*loaded, codec);
                        std::vector<U> decoded;
                        decode(*loaded, decoded);
                        verify_logical_source3(decoded, source, valid);

                        // Independent policy check: inspect complete leaf rows, including
                        // padding hidden by the logical CHUNKS truncation.
                        for (U off = 0; off < n; off += V) {
                            const U take = std::min(V, n - off);
                            U representative = 0;
                            for (U i = 0; i < take; ++i) {
                                if (valid3(valid, off + i)) { representative = source[off + i]; break; }
                            }
                            std::vector<U> block;
                            if (family != 0) {
                                const Node& chunks = family == 3 ? *loaded->children[0] : *loaded;
                                decode(*chunks.children[off / V], block);
                                if (family == 3) {
                                    for (U& code : block) {
                                        need(code < loaded->vals.size(), "physical-fill fixture dictionary bound");
                                        code = loaded->vals[code];
                                    }
                                }
                                need(block.size() == V, "physical-fill physical block rows");
                            }
                            for (U i = 0; i < take; ++i) {
                                const U expected = (mode & 1U) && !valid3(valid, off + i)
                                    ? representative : source[off + i];
                                need(decoded[off + i] == expected, "physical-fill NULL policy");
                                if (family != 0) need(block[i] == expected, "physical-fill leaf logical values");
                            }
                            if (family != 0) {
                                for (U i = take; i < V; ++i) {
                                    // Without explicit tail fill, dictionary code padding
                                    // is zero (dictionary entry 0), not necessarily value 0.
                                    const U expected = mode & 2U ? representative
                                        : (family == 3 ? loaded->vals[0] : 0);
                                    need(block[i] == expected, "physical-fill tail policy");
                                }
                            }
                        }

                        std::vector<Col> cs;
                        cs.push_back({0, codec, std::move(loaded)});
                        const Catalog views = make_views(cs);
                        B expected_bank;
                        std::array<B, 4> actual_banks;
                        for (U op = 0; op <= GE; ++op) {
                            for (int64_t literal : std::array<int64_t, 9>{lo - 1, lo, lo + 1, -1, 0, 1, hi - 1, hi, hi + 1}) {
                                for (bool null_literal : {false, true}) {
                                    B expected(valid.size(), 0);
                                    for (U i = 0; i < n; ++i) {
                                        bit(expected, i, valid3(valid, i) && !null_literal &&
                                            signed_test(original[i], op, literal));
                                    }
                                    expected_bank.insert(expected_bank.end(), expected.begin(), expected.end());
                                    Pred pred{Op(op), 0, {}};
                                    int constant = -1;
                                    if (null_literal) constant = 0;
                                    else if (literal < lo || literal > hi) {
                                        constant = int(signed_test(lo, op, literal));
                                        need(constant == int(signed_test(hi, op, literal)), "physical-fill bound fold");
                                    } else pred.value = U(literal - lo);
                                    std::array<B, 4> out;
                                    for (B& b : out) b.assign(valid.size(), 0);
                                    if (constant >= 0) {
                                        if (constant) for (B& b : out) b = valid;
                                    } else {
                                        auto plan = lower_fused(*cs[0].root, pred, views);
                                        run_fused<false>(plan, views, out[0]);
                                        run_fused<true>(plan, views, out[1]);
                                        expert_fused<false>(*cs[0].root, codec, pred, out[2], views);
                                        expert_fused<true>(*cs[0].root, codec, pred, out[3], views);
                                        for (B& b : out) for (size_t w = 0; w < b.size(); ++w) b[w] &= valid[w];
                                    }
                                    for (size_t arm = 0; arm < out.size(); ++arm) {
                                        need(out[arm] == expected, "physical-fill signed/NULL answer");
                                        actual_banks[arm].insert(actual_banks[arm].end(), out[arm].begin(), out[arm].end());
                                        ++answers;
                                    }
                                }
                            }
                        }
                        for (const B& bank : actual_banks) {
                            need(bank == expected_bank, "physical-fill complete answer bank");
                            ++banks;
                        }
                        ++trees;
                    }
                }
            }
        }
    }
    std::cout << "{\"physical_fill_trees\":" << trees
              << ",\"physical_fill_full_banks\":" << banks
              << ",\"physical_fill_full_answers\":" << answers << "}\n";
    return 0;
}

static Table3 construct3(const std::string&dir){Table3 t;t.binding=binding3(dir+"/binding.txt");t.meta=metadata3(dir+"/columns.tsv");
 for(const auto&m:t.meta){auto a=raw(dir,m.id);need(a.size()==m.n,"raw rows");auto valid=validity3(dir+"/col"+std::to_string(m.id)+".valid.bitmap",m.n);
  for(U j=0;j<m.n;++j){need(m.width==32||a[j]<=65535,"source bias width");if(!(valid3(valid,j)||a[j]==0)) throw std::runtime_error(std::string("NULL placeholder bias j=")+std::to_string(j)+" id="+std::to_string(m.id)+" n="+std::to_string(m.n));if(!m.nullable)need(valid3(valid,j),"NOT NULL validity");}
  U codec=m.family==5?2:m.family;t.cs.push_back({m.id,codec,build_factorial3(a,valid,m.family)});shape(*t.cs.back().root,codec);t.valid.push_back(std::move(valid));}
 return t;
}
static void save3(const std::string&path,const Table3&t){std::ofstream o(path,std::ios::binary);need(bool(o),"encoded output");o.write("BSCOH03\n",8);o.write(t.binding.data(),40);wr<U>(o,U(t.cs.size()));
 for(U j=0;j<t.cs.size();++j){const auto&m=t.meta[j];wr(o,m.id);wr(o,m.width);wr(o,m.nullable);wr(o,m.family);wr(o,m.n);wr(o,t.cs[j].codec);wv(o,t.valid[j]);save_node(o,*t.cs[j].root);}o.flush();need(bool(o),"encoded save");}
static Table3 load3(const std::string&path,const std::string&binding){std::ifstream i(path,std::ios::binary);need(bool(i),"encoded input");char magic[8],source[40];i.read(magic,8);i.read(source,40);need(bool(i)&&std::string(magic,8)=="BSCOH03\n"&&std::string(source,40)==binding,"encoded source binding");Table3 t;t.binding=binding;U cols=rd<U>(i);need(cols>0&&cols<=100,"encoded columns");
 for(U j=0;j<cols;++j){Meta3 m{rd<U>(i),rd<U>(i),rd<U>(i),rd<U>(i),rd<U>(i)};U codec=rd<U>(i);need((m.width==16||m.width==32)&&m.nullable<=1&&family3(m.family)&&codec==(m.family==5?2:m.family)&&m.n>0&&m.n<=100000000,"encoded metadata");for(const auto&p:t.meta)need(p.id!=m.id&&p.n==m.n,"encoded unique/common rows");auto valid=rv<uint64_t>(i);need(valid.size()==(size_t(m.n)+63)/64,"encoded validity length");if(m.n%64)need(valid.back()>>(m.n%64)==0,"encoded validity padding");if(!m.nullable)for(U k=0;k<m.n;++k)need(valid3(valid,k),"encoded NOT NULL");auto root=load_node(i);need(root->n==m.n,"encoded node rows");shape(*root,codec);if(m.family==5)for(const auto&b:root->children)need(b->pos.empty()&&b->vals.empty(),"plain FFOR empty patch");t.cs.push_back({m.id,codec,std::move(root)});t.meta.push_back(m);t.valid.push_back(std::move(valid));}
 need(i.peek()==std::char_traits<char>::eof(),"encoded suffix");return t;
}
static void verify3(const Table3&t,const std::string&dir){auto expected=metadata3(dir+"/columns.tsv");need(expected.size()==t.meta.size(),"source column count");uint64_t values=0,valid_count=0;
 for(U j=0;j<t.cs.size();++j){const auto&m=t.meta[j],&e=expected[j];need(m.id==e.id&&m.width==e.width&&m.nullable==e.nullable&&m.family==e.family&&m.n==e.n,"source metadata");auto source=raw(dir,m.id);std::vector<U>decoded;decode(*t.cs[j].root,decoded);verify_logical_source3(decoded,source,t.valid[j]);auto valid=validity3(dir+"/col"+std::to_string(m.id)+".valid.bitmap",m.n);need(valid==t.valid[j],"validity reconstruction");for(auto w:valid)valid_count+=__builtin_popcountll(w);values+=m.n;}
 std::cout<<"{\"checked_nullable_logical_rows\":"<<values<<",\"non_null_values\":"<<valid_count<<"}\n";
}
static void evaluate3(const Col&c,const Catalog&views,const B&valid,const Query3&q,const std::string&method,B&out){
 if(q.constant>=0){if(q.constant)out=valid;return;}
 if(method=="generic_full"||method=="generic_set"){auto f=lower_fused(*c.root,q.query.p,views);if(method=="generic_set")run_fused<true>(f,views,out);else run_fused<false>(f,views,out);}
 else if(method=="expert_set")expert_fused<true>(*c.root,c.codec,q.query.p,out,views);
 else if(method=="compressed_scan")scan_bulk(*c.root,c.codec,q.query.p,out);
 else throw std::runtime_error("evaluation method");
 for(U k=0;k<out.size();++k)out[k]&=valid[k];
}
static bool compare_signed3(int64_t x,U op,int64_t y){switch(op){case EQ:return x==y;case NE:return x!=y;case LT:return x<y;case LE:return x<=y;case GT:return x>y;case GE:return x>=y;}throw std::runtime_error("signed opcode");}
static Query3 lower_signed3(U op,int64_t value,U width,bool null_literal=false){int64_t lo=-(int64_t(1)<<(width-1)),hi=(int64_t(1)<<(width-1))-1;Query3 q{{0,0,{Op(op),0,{}}},-1};
 if(null_literal)q.constant=0;else if(value<lo||value>hi){q.constant=int(compare_signed3(lo,op,value));need(q.constant==int(compare_signed3(hi,op,value)),"type-domain constant");}else q.query.p.value=U(value-lo);return q;
}
static int fixtures3(){uint64_t cases=0;
 for(U width:{16U,32U})for(U n:{1U,63U,64U,65U,1023U,1031U})for(U family:{0U,2U,3U,5U}){
  int64_t lo=-(int64_t(1)<<(width-1)),hi=(int64_t(1)<<(width-1))-1;std::array<int64_t,7>base={lo,lo+1,-1,0,1,hi-1,hi};std::vector<U>a(n);B valid((n+63)/64,0);std::vector<int64_t>signed_values(n);
  for(U i=0;i<n;++i){signed_values[i]=base[(i/11)%base.size()];bool live=i%13!=0;bit(valid,i,live);a[i]=live?U(signed_values[i]-lo):0;}
  std::vector<Col>cs;cs.push_back({0,family==5?2:family,build3(a,family)});auto views=make_views(cs);
  for(U op=0;op<=GE;++op)for(int64_t literal:std::array<int64_t,7>{lo-1,lo,-1,0,1,hi,hi+1})for(bool null_literal:{false,true}){auto q=lower_signed3(op,literal,width,null_literal);B expected(valid.size(),0);for(U i=0;i<n;++i)bit(expected,i,!null_literal&&valid3(valid,i)&&compare_signed3(signed_values[i],op,literal));for(const auto&method:{"generic_full","generic_set","expert_set","compressed_scan"}){B out(valid.size(),0);evaluate3(cs[0],views,valid,q,method,out);need(out==expected,"signed/null/full-vector fixture");++cases;}}
 }
 std::cout<<"{\"round3_signed_null_composition_cases\":"<<cases<<"}\n";return 0;
}
static int main3(int argc,char**argv){need(argc>=2,"mode");std::string mode=argv[1];if(mode=="selftest_round3")return fixtures3();if(mode=="selftest4")return main_v4(argc,argv);
 if(mode=="build_round3"){need(argc==4,"build_round3 prepared encoded");auto start=Clock::now();auto t=construct3(argv[2]);double build_ms=ms(start);start=Clock::now();save3(argv[3],t);double save_ms=ms(start);start=Clock::now();auto re=load3(argv[3],t.binding);verify3(re,argv[2]);std::cout<<"{\"build_ms\":"<<build_ms<<",\"save_ms\":"<<save_ms<<",\"reload_verify_ms\":"<<ms(start)<<"}\n";return 0;}
 need(mode=="query_round3"&&argc==8,"query_round3 encoded prepared queries method bitmap metrics");auto setup=Clock::now();std::string dir=argv[3],method=argv[5];bool packed=method=="packed_width";need(packed||method=="generic_full"||method=="generic_set"||method=="expert_set"||method=="compressed_scan","method");auto qs=queries3(argv[4]);Table3 table;std::map<U,std::vector<uint16_t>>p16;std::map<U,std::vector<U>>p32;Catalog views;double view_build_ms=0;
 if(packed){table.binding=binding3(dir+"/binding.txt");table.meta=metadata3(dir+"/columns.tsv");for(const auto&m:table.meta){std::string prefix=dir+"/col"+std::to_string(m.id);if(m.width==16){p16[m.id]=raw_block<uint16_t>(prefix+".biased.u16");need(p16[m.id].size()==m.n,"packed16 rows");}else{p32[m.id]=raw_block<U>(prefix+".biased.u32");need(p32[m.id].size()==m.n,"packed32 rows");}auto valid=validity3(prefix+".valid.bitmap",m.n);if(!m.nullable)for(U k=0;k<m.n;++k)need(valid3(valid,k),"packed NOT NULL validity");table.valid.push_back(std::move(valid));}}
 else{table=load3(argv[2],binding3(dir+"/binding.txt"));auto tv=Clock::now();views=make_views(table.cs);view_build_ms=ms(tv);}
 U n=table.meta[0].n;for(const auto&q:qs){auto m=std::find_if(table.meta.begin(),table.meta.end(),[&](const Meta3&m){return m.id==q.query.col;});need(m!=table.meta.end(),"query source column");need(q.constant!=-1||m->width==32||q.query.p.value<=65535,"source-width literal");}double setup_ms=ms(setup);auto t=Clock::now();size_t stride=(size_t(n)+63)/64;B bank(stride*qs.size(),0);
 for(const auto&q:qs){U j=U(std::find_if(table.meta.begin(),table.meta.end(),[&](const Meta3&m){return m.id==q.query.col;})-table.meta.begin());B out(stride,0);
  if(packed){if(q.constant>=0){if(q.constant)out=table.valid[j];}else{if(table.meta[j].width==16)bulk_words(p16.at(q.query.col).data(),n,q.query.p,out,0);else bulk_words(p32.at(q.query.col).data(),n,q.query.p,out,0);for(U k=0;k<out.size();++k)out[k]&=table.valid[j][k];}}
  else evaluate3(table.cs[j],views,table.valid[j],q,method,out);
  std::copy(out.begin(),out.end(),bank.begin()+size_t(q.query.id)*stride);
 }
 auto rss=resident_kib();double bank_ms=ms(t);std::ofstream o(argv[6],std::ios::binary),m(argv[7]);need(bool(o)&&bool(m),"output");o.write(reinterpret_cast<const char*>(bank.data()),bank.size()*8);o.flush();need(bool(o),"output write");
 m<<"{\"record\":\"setup\",\"setup_ms\":"<<setup_ms<<",\"view_build_ms\":"<<view_build_ms<<",\"view_count\":"<<views.views.size()<<",\"view_owned_capacity_bytes\":"<<sizeof(Catalog)+views.views.capacity()*sizeof(View)+views.ends.capacity()*sizeof(uint16_t)<<"}\n";
 m<<"{\"record\":\"bank\",\"bank_ms\":"<<bank_ms<<",\"query_count\":"<<qs.size()<<",\"rows\":"<<n<<",\"output_bytes\":"<<bank.size()*8<<",\"post_bank_rss_kib\":"<<rss<<",\"full_bank_allocation_copy_validity_charged\":true}\n";return 0;
}
int frozen_cohort_entry(int argc,char**argv){try{return main3(argc,argv);}catch(const std::exception&e){std::cerr<<"REJECT: "<<e.what()<<'\n';return 2;}}

// Explicit selectors are outside every measured setup/bank phase. All native
// arms in this binary share them; no source column/query ID selects a kernel.
static int factorial_entry(int argc,char**argv){
 need(argc>=6,"--bitmap-kernel scalar|sse2 --physical-fill 0|1|2|3 command");
 need(std::string(argv[1])=="--bitmap-kernel"&&std::string(argv[3])=="--physical-fill","factorial flag order");
 std::string kernel=argv[2],fill=argv[4];
 need(kernel=="scalar"||kernel=="sse2","bitmap kernel selector");
 need(fill=="0"||fill=="1"||fill=="2"||fill=="3","physical fill selector");
 physical_fill_mode=unsigned(fill[0]-'0');
 const bool available=compare_mask_available();
 need(kernel!="sse2"||available,"requested SSE2 unavailable; no silent substitution");
 compare_mask_enabled=kernel=="sse2";
 std::cout<<"{\"bitmap_kernel\":\""<<kernel<<"\",\"physical_fill_mode\":"<<physical_fill_mode
          <<",\"compiled_sse2\":"<<FACTORIAL_COMPILED_SSE2<<",\"runtime_sse2\":"<<int(available)
          <<",\"logical_null_payload_semantically_ignored\":"<<int(bool(physical_fill_mode&1U))<<"}\n";
 std::vector<char*> forwarded{argv[0]};for(int i=5;i<argc;++i)forwarded.push_back(argv[i]);
 const std::string mode=forwarded[1];
 if(mode=="selftest_compare_mask"){need(forwarded.size()==2,"compare-mask fixture arguments");selftest_compare_mask();return 0;}
 if(mode=="selftest_guard_pages"){need(forwarded.size()==2,"guard-page fixture arguments");selftest_compare_mask_guard();return 0;}
 if(mode=="selftest_physical_fill"){need(forwarded.size()==2,"physical-fill fixture arguments");return selftest_physical_fill3();}
 return main3(int(forwarded.size()),forwarded.data());
}
int frozen_factorial_outer_entry(int argc,char**argv){try{return factorial_entry(argc,argv);}catch(const std::exception&e){std::cerr<<"REJECT: "<<e.what()<<'\n';return 2;}}
